<?php
declare(strict_types=1);
$id='CHAR(36) CHARACTER SET ascii COLLATE ascii_bin';$ref='VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin';$hash='CHAR(64) CHARACTER SET ascii';
$sql=[
"CREATE TABLE cloud_meter_tariffs(id $id PRIMARY KEY,account_id $id NOT NULL,policy_json LONGTEXT NOT NULL CHECK(JSON_VALID(policy_json)),fingerprint $hash NOT NULL,actor_id $id NOT NULL,provenance VARCHAR(16) NOT NULL CHECK(provenance='MOCK'),created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(account_id) REFERENCES cloud_accounts(id)) ENGINE=InnoDB",
"CREATE TABLE mock_cloud_meter_events(id $id PRIMARY KEY,account_id $id NOT NULL,kind VARCHAR(16) NOT NULL CHECK(kind IN ('USAGE','INVOICE')),provider_ref $ref NOT NULL,payload_encrypted LONGTEXT NOT NULL,fingerprint $hash NOT NULL,received_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_cloud_meter_reference(account_id,kind,provider_ref),FOREIGN KEY(account_id) REFERENCES cloud_accounts(id)) ENGINE=InnoDB",
"CREATE TABLE cloud_cost_work(id $id PRIMARY KEY,instance_id $id NOT NULL,account_id $id NOT NULL,usage_ref $ref NOT NULL,fingerprint $hash NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','UNVERIFIED','REVIEW','COSTED_MOCK')),safe_code VARCHAR(64) NOT NULL DEFAULT 'METERING_REQUIRED',checked_at DATETIME(6) NULL,proposal_checked_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_cloud_cost_usage(account_id,usage_ref),KEY ix_cloud_cost_fair(status,checked_at,created_at,id),FOREIGN KEY(instance_id) REFERENCES cloud_instances(id)) ENGINE=InnoDB",
"CREATE TABLE cloud_usage_costs(id $id PRIMARY KEY,instance_id $id NOT NULL,account_id $id NOT NULL,resource_id $id NOT NULL,meter_event_id $id NOT NULL UNIQUE,tariff_id $id NOT NULL,usage_ref $ref NOT NULL,sequence_no BIGINT UNSIGNED NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,currency CHAR(3) CHARACTER SET ascii NOT NULL,total_minor BIGINT NOT NULL CHECK(total_minor>=0),calculation_encrypted LONGTEXT NOT NULL,fingerprint $hash NOT NULL,journal_id $id NULL UNIQUE,provenance VARCHAR(16) NOT NULL CHECK(provenance='MOCK'),created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_cloud_cost_meter(account_id,usage_ref),UNIQUE KEY uq_cloud_cost_sequence(instance_id,sequence_no),KEY ix_cloud_cost_interval(instance_id,starts_at,ends_at),FOREIGN KEY(id) REFERENCES cloud_cost_work(id),FOREIGN KEY(meter_event_id) REFERENCES mock_cloud_meter_events(id),FOREIGN KEY(tariff_id) REFERENCES cloud_meter_tariffs(id),FOREIGN KEY(journal_id) REFERENCES finance_journals(id)) ENGINE=InnoDB",
"CREATE TABLE cloud_cost_reconciliations(id $id PRIMARY KEY,instance_id $id NOT NULL,invoice_event_id $id NOT NULL,basis_hash $hash NOT NULL,status VARCHAR(24) NOT NULL CHECK(status IN ('UNVERIFIED','REVIEW','MATCHED_MOCK')),evidence_encrypted LONGTEXT NOT NULL,fingerprint $hash NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_cloud_cost_invoice(instance_id,invoice_event_id,basis_hash),FOREIGN KEY(invoice_event_id) REFERENCES mock_cloud_meter_events(id)) ENGINE=InnoDB",
"CREATE TABLE cloud_cost_invoice_bindings(cost_id $id PRIMARY KEY,reconciliation_id $id NOT NULL,FOREIGN KEY(cost_id) REFERENCES cloud_usage_costs(id),FOREIGN KEY(reconciliation_id) REFERENCES cloud_cost_reconciliations(id)) ENGINE=InnoDB",
"CREATE TABLE catalog_cloud_cost_links(proposal_id $id PRIMARY KEY,cost_id $id NOT NULL,instance_id $id NOT NULL,base_price_id $id NOT NULL,snapshot_encrypted LONGTEXT NOT NULL,fingerprint $hash NOT NULL,auto_publish_allowed BOOLEAN NOT NULL CHECK(auto_publish_allowed=FALSE),provenance VARCHAR(16) NOT NULL CHECK(provenance='MOCK'),UNIQUE KEY uq_cloud_cost_proposal(cost_id,base_price_id),FOREIGN KEY(proposal_id) REFERENCES catalog_cost_proposals(id),FOREIGN KEY(cost_id) REFERENCES cloud_usage_costs(id)) ENGINE=InnoDB",
"CREATE TABLE catalog_cloud_cost_approvals(proposal_id $id PRIMARY KEY,actor_id $id NOT NULL,session_id $id NOT NULL,identity_version BIGINT UNSIGNED NOT NULL,fingerprint $hash NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(proposal_id) REFERENCES catalog_cloud_cost_links(proposal_id)) ENGINE=InnoDB",
"CREATE TABLE catalog_cloud_cost_publications(proposal_id $id PRIMARY KEY,price_id $id NOT NULL UNIQUE,actor_id $id NOT NULL,confirmation_id $id NOT NULL UNIQUE,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(proposal_id) REFERENCES catalog_cloud_cost_approvals(proposal_id),FOREIGN KEY(price_id) REFERENCES catalog_prices(id)) ENGINE=InnoDB",
"CREATE TRIGGER cloud_cost_work_binding BEFORE UPDATE ON cloud_cost_work FOR EACH ROW BEGIN IF OLD.id<>NEW.id OR OLD.instance_id<>NEW.instance_id OR OLD.account_id<>NEW.account_id OR OLD.usage_ref<>NEW.usage_ref OR OLD.fingerprint<>NEW.fingerprint OR (OLD.status='COSTED_MOCK' AND NEW.status<>'COSTED_MOCK') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable Cloud cost input'; END IF; END",
"CREATE TRIGGER cloud_cost_work_delete BEFORE DELETE ON cloud_cost_work FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Cloud cost work retained'",
];
foreach(['cloud_meter_tariffs','mock_cloud_meter_events','cloud_usage_costs','cloud_cost_reconciliations','cloud_cost_invoice_bindings','catalog_cloud_cost_links','catalog_cloud_cost_approvals','catalog_cloud_cost_publications'] as $table){foreach(['UPDATE','DELETE'] as $verb){$sql[]="CREATE TRIGGER {$table}_".strtolower($verb)." BEFORE $verb ON $table FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable Cloud cost evidence'";}}
return $sql;
